// === Tab: mySketch ===
//Pierre MARZIN 01/2019
//I'm using p5js Sound library to load and analyse 
//a song. Then, I pass the results of the analysis, as a texture, to the fragment shader.
//This shader will transform these informations in a 3d "landscape",
//using distance functions, and a rotating camera...
var button, input, fft, sound;
let maxVolume = 0.1;
let adjustedVolume;
let analyzer;
var img;
var program;
var gl;

var swidth = 1920 / 2;
var sheight = 1080 / 2;

function setupFile() {  
	const input = createFileInput(gotFile);
  input.position(width - 10, 0);
	input.style('z-index', 100);
	input.style('opacity', 0.1);
}

function setupSources() {
	const div = createDiv(`<div>Muzică: jam</div>
<div>Imagine: https://www.openprocessing.org/sketch/768849</div>
<div id="stats">...</div>
`);
	div.style('z-index', 100);
	div.style('color', 'red');
	div.style('background-color', 'rgba(0, 0, 0, 0.2)');
	div.style('font-family', 'Impact');
	div.style('padding', '10px');
	//div.style('position', 'absolute');
	//div.style('top', '100');
	div.position(0, 0);
	//document.querySelector('body').appendElement(el);
}

function setup() {
	const canvas = createCanvas(swidth, sheight,WEBGL);
	canvas.drop(gotFile);
	setupFile();
	setupSources();

  pixelDensity(1);
	//img is the image where the spectrum data will be stored
	img=createImage(256,1);
	img.loadPixels();
  rectMode(CENTER);
	input=new p5.AudioIn();
	input.start();
	//shader is loaded with vert and frag definitions
  program = createShader(vert, frag);
	//cf Sound library doc
  fft = new p5.FFT();
	fft.setInput(input);
	analyzer = new p5.Amplitude();
	analyzer.setInput(input);
}
function draw() {  
	volume = input.getLevel();
	if(sound) {
		volume = analyzer.getLevel();
	}
  if(volume > maxVolume) {
		maxVolume = volume;
	}
	adjustedVolume = map(volume, 0, maxVolume, 0, 0.9999);

	//Once you clicked or touch
		//level reflects sound amplitude
    var level=pow(adjustedVolume,0.6);

    var spectrum = fft.analyze();
		//spectrum is an array, containing the levels of each frequency
		//I convert it into a P5 Image, so to pass it to the shader as a texture
		for (var i = 0; i<4*256; i+=4) {
			var s=spectrum[i/4];
      img.pixels[i]=s;
      img.pixels[i+1]=s;
      img.pixels[i+2]=s;
      img.pixels[i+3]=s;
    }
		img.updatePixels();
		this.shader(program);
		//shaders uniforms are fed with our data
    program.setUniform('volume', level);
		program.setUniform('iMouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
    program.setUniform('iResolution', [width, height]);
    program.setUniform('iTime', millis()/1000);
    program.setUniform('iChannel0',img);
		//the scene is rendered as a rectangle
    rect(0, 0, width, height);

	let fps = frameRate();
  document.querySelector('#stats').innerHTML = fps.toFixed(2) + ' - ' + (sound ? sound.currentTime().toFixed(2) : '0');
}

function gotFile(file) {
	if (file.type === 'image') {
    const img = createImg(file.data).hide();
    image(img, 0, 0, width, height);
	} else if (file.type === 'audio') {
    sound = loadSound(file, function successLoaded () {
			background(0);
			sound.amp(0.5)
			sound.loop();
			analyzer.setInput(sound);
			fft.setInput(sound);
		});
  } else {
    console.log('Not an image file!');
  }
}
let statsAndMusicGraphics;
function drawStatsAndMusic(ctx, useTexture) {
	if(!statsAndMusicGraphics) {
		statsAndMusicGraphics = createGraphics(width, height);
		//statsAndMusicGraphics.background(255);
	}
	if(!ctx) {
		ctx = statsAndMusicGraphics;
	}

	ctx.textFont('Impact');
	var fps = frameRate();
  ctx.fill(255,0,0);
	ctx.strokeWeight(2)
  ctx.stroke(3);
	ctx.textSize(18)
  ctx.text(fps.toFixed(2) + ' - ' + (sound ? sound.currentTime().toFixed(2) : '0'), 40, 45);

	ctx.fill(0);
	const hDelta = -30;
	const wDelta = -30;
	ctx.rect(width - 320 + wDelta, height - 30 + hDelta, 400, 50);
	ctx.fill(255, 0, 0);
	ctx.textFont('Impact');
	ctx.text('Muzica: robot clock ggkbi.csb.app' , width - 300 + wDelta, height - 10 + hDelta);

	if(useTexture) {
		texture(ctx);
		plane(width, height);
	}
}



// === Tab: shader ===
var frag=`
// adapted from a Shader Created by inigo quilez - iq/2013
// License Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported License.
#ifdef GL_ES
  precision highp float;
#endif

uniform float iTime;
uniform float volume;
uniform vec2 iMouse;
uniform vec2 iResolution;
uniform sampler2D iChannel0;
varying highp vec2 vVertTexCoord;

vec3 hash3( float n )
{
    return fract(sin(vec3(n,n+1.0,n+2.0))*vec3(43758.5453123,22578.1459123,19642.3490423));
}

vec3 snoise3( in float x )
{
    float p = floor(x);
    float f = fract(x);
    f = f*f*(3.0-2.0*f);
    return -1.0 + 2.0*mix( hash3(p+0.0), hash3(p+1.0), f );
}

float freqs[16];

vec3 distanceLines( in vec3 ro, in vec3 rd, vec3 pa, vec3 pb )
{
	vec3 ba = pb - pa;
	vec3 oa = ro - pa;	
	float oad  = dot( oa, rd );
	float dba  = dot( rd, ba );
	float baba = dot( ba, ba );
	float oaba = dot( oa, ba );
	vec2 th = vec2( -oad*baba + dba*oaba, oaba - oad*dba ) / (baba - dba*dba);
	th.x = max(   th.x, 0.0 );
	th.y = clamp( th.y, 0.0, 1.0 );
	vec3 p = pa + ba*th.y;
	vec3 q = ro + rd*th.x;
	//float l=1.4*length( p-q );
	//return vec3(min(l*4.0*pow(volume,.5)*dot(q,p),l), th );
return vec3( length( p-q ), th );
}

vec3 castRay( vec3 ro, vec3 rd, float linesSpeed )
{
	vec3 col = vec3(0.0);
	float mindist = 10000.0;
	vec3 p = vec3(0.2);
	float h = 0.0;
	float rad = 0.04+ 0.15*freqs[0];
	float mint = 0.0;
  for( int i=0; i<128; i++ )//noprotect
	{
		vec3 op = p;
		p  = 1.25*1.0*normalize(snoise3( 64.0*h + linesSpeed*0.015*iTime ));
		vec3 dis = distanceLines( ro, rd, op, p );
		vec3 lcol = 0.6 + 0.4*sin( 62.831*h +vec3(0.0,0.6,0.9)); //vec3(abs(cos(0.25*iTime)),abs(sin(0.15*iTime)),abs(cos(0.65*iTime))
		float m =pow( texture2D( iChannel0, vec2(h*0.5,0.2) ).x, 2.0 )*(1.0+2.0*h);
		float f = 1.0 - 4.0*dis.z*(1.0-dis.z);
		float width = 1240.0 - 1000.0*f;
		float ff = exp(-0.06*dis.y*dis.y*dis.y);
		ff *= m;
		col += 0.3*lcol*exp( -0.3*width*dis.x*dis.x )*ff;
		col += 0.5*lcol*exp( -8.0*width*dis.x*dis.x )*ff;
		h += 1.0/128.0;
	}
    return col;
}
vec3 czm_saturation(vec3 rgb, float adjustment)
{
    // Algorithm from Chapter 16 of OpenGL Shading Language
    const vec3 W = vec3(0.2125, 0.7154, 0.0721);
    vec3 intensity = vec3(dot(rgb, W));
    return mix(intensity, rgb, adjustment);
}
void main()
{
	vec2 q = gl_FragCoord.xy/iResolution.xy;
  vec2 p = -1.0+2.0*q;
	p.x *= iResolution.x/iResolution.y;
  vec2 mo = iMouse.xy/iResolution.xy;		 
	float time = iTime;
	for( int i=0; i<2; i++ ) freqs[i] =clamp( 1.9*pow( texture2D(iChannel0, vec2( 0.05 + 0.5*float(i)/16.0, 0.25 ) ).x, 3.0 ), 0.0, 1.0 );

	// camera	
	vec3 ta = vec3( 0.0, 0.0, 0.0 );	
  float camSpeed =1.0+volume;	
	ta  = 0.2*vec3( cos(0.1*time), 0.0*sin(0.1*time), sin(0.07*time) );
	vec3 ro = vec3(2.0*cos(camSpeed*0.5*time+6.28*mo.x), 0.0, 2.0*sin(camSpeed*0.5*time+6.2831*mo.x) );
	float roll = .25*sin(camSpeed*time);

	// camera tx
	vec3 cw = normalize( ta-ro );
	vec3 cp = vec3( sin(roll), cos(roll),0.0 );
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv = normalize( cross(cu,cw) );
	vec3 rd = normalize( p.x*cu + p.y*cv + 1.2*cw );
  rd.xy += (1.0-volume)*0.025*vec2( sin(34.0*q.y), cos(34.0*q.x) );
	rd = normalize(rd);		
	ro *= 1.0 -.5*freqs[1];
  vec3 col = castRay( ro, rd, 15.0*volume );
  col = col*col*2.4;
	col *= 0.15+0.85*pow( 16.0*q.x*q.y*(1.0-q.x)*(1.0-q.y), 0.15 );
	col=czm_saturation(col,4.0*volume);
  gl_FragColor=vec4( col, 1.0 );
}
`;
var vert=`
attribute vec3 aPosition;
attribute vec3 aNormal;
attribute vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

varying vec3 vVertexNormal;
varying highp vec2 vVertTexCoord;

void main(void) {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
  vVertexNormal = normalize(vec3( uNormalMatrix * aNormal ));
  vVertTexCoord = aTexCoord;
}
`;

